DATA = json.loads(JSON_DATA)

import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from app.mongodb import get_conn
import json as _json

# Key that MUST be present on a row for it to belong to that table
TABLE_REQUIRED_KEY = {
    "customers":                    "customer_name",
    "products":                     "sku",
    "suppliers":                    "id",          # fallback – insert whatever has no better key
    "users":                        "username",
    "shelves":                      "shelf_code",
    "inventory_health_alerts":      "health_type",
    "inventory_action_suggestions": "suggestion_type",
    "product_demand_analytics":     "demand_score",
    "product_logistics_metrics":    "lead_time",
}

def get_table_columns(cur, table):
    cur.execute(
        "SELECT column_name FROM information_schema.columns "
        "WHERE table_name = %s AND is_generated = 'NEVER'", 
        (table,)
    )
    return set(row["column_name"] for row in cur.fetchall())

def upsert_rows(cur, table, rows, pk="id"):
    required_key = TABLE_REQUIRED_KEY.get(table)
    valid_rows   = [r for r in rows if required_key is None or required_key in r]
    if not valid_rows:
        return 0
    
    # Filter columns to only what exists in the database
    valid_cols = get_table_columns(cur, table)
    if not valid_cols:
        print(f"  skip  {table} (table does not exist in DB)")
        return 0

    inserted = 0
    for row in valid_rows:
        # Dynamically map any missing *_id relations to a valid DB id
        if not hasattr(upsert_rows, "valid_ids"):
            upsert_rows.valid_ids = {}
            upsert_rows.fallbacks = {}
            
        for k, v in list(row.items()):
            if k.endswith("_id") and isinstance(v, int):
                if k not in upsert_rows.valid_ids:
                    ref_table = k[:-3] + "s"
                    if ref_table == "batchs": ref_table = "batches"
                    elif ref_table == "categorys": ref_table = "categories"
                    elif ref_table == "addresss": ref_table = "addresses"
                    elif ref_table == "inventory_ids": ref_table = "inventory"
                    try:
                        cur.execute("SAVEPOINT fetch_ids")
                        cur.execute(f"SELECT id FROM {ref_table}")
                        ids = set(r["id"] for r in cur.fetchall())
                        upsert_rows.valid_ids[k] = ids
                        upsert_rows.fallbacks[k] = next(iter(ids)) if ids else None
                        cur.execute("RELEASE SAVEPOINT fetch_ids")
                    except Exception as e:
                        cur.execute("ROLLBACK TO SAVEPOINT fetch_ids")
                        upsert_rows.valid_ids[k] = set()
                        upsert_rows.fallbacks[k] = None
                        
                v_set = upsert_rows.valid_ids[k]
                if v_set and v not in v_set and upsert_rows.fallbacks[k] is not None:
                    row[k] = upsert_rows.fallbacks[k]

        # Keep only keys that match an actual DB column
        filtered_row = {k: v for k, v in row.items() if k in valid_cols}
        if not filtered_row:
            continue
            
        cols   = list(filtered_row.keys())
        values = [_json.dumps(v) if isinstance(v, dict) else v for v in filtered_row.values()]
        placeholders = ", ".join(["%s"] * len(cols))
        col_str      = ", ".join(f'"{c}"' for c in cols)
        
        # Build ON CONFLICT clause dynamically
        conflict_clause = ""
        if pk in valid_cols:
            conflict_clause = f' ON CONFLICT ("{pk}") DO NOTHING'
            
        sql = f'INSERT INTO "{table}" ({col_str}) VALUES ({placeholders}){conflict_clause}'
        try:
            cur.execute("SAVEPOINT row_insert")
            cur.execute(sql, values)
            cur.execute("RELEASE SAVEPOINT row_insert")
            inserted += cur.rowcount
        except Exception as e:
            cur.execute("ROLLBACK TO SAVEPOINT row_insert")
            print(f"  -  Skip row in {table}: {e}".splitlines()[0])
    return inserted

# Insertion order respects FK dependencies
TABLE_ORDER = [
    ("users",                        "id"),
    ("customers",                    "id"),
    ("products",                     "id"),
    ("suppliers",                    "id"),
    ("shelves",                      "id"),
    ("inventory",                    "id"),
    ("purchase_orders",              "id"),
    ("purchase_order_items",         "id"),
    ("receipts",                     "id"),
    ("receipt_items",                "id"),
    ("sales_orders",                 "id"),
    ("sales_order_items",            "id"),
    ("bundles",                      "id"),
    ("bundle_items",                 "id"),
    ("promotions",                   "id"),
    ("reorder_policy",               "id"),
    ("inventory_optimization_config","id"),
    ("inventory_health_analytics",   "id"),
    ("inventory_health_status",      "id"),
    ("inventory_action_suggestions", "id"),
    ("product_demand_analytics",     "id"),
    ("product_logistics_metrics",    "id"),
]

# Also collect ALL products regardless of which JSON key they live under
def collect_products():
    products = list(DATA.get("products", []))
    # Some seeds embed products inside other arrays
    for key, rows in DATA.items():
        if key == "products":
            continue
        for row in (rows or []):
            if isinstance(row, dict) and "sku" in row and row not in products:
                products.append(row)
    return products

def main():
    conn = get_conn()
    cur  = conn.cursor()
    total = 0
    try:
        conn.autocommit = False

        # 1. Customers (filter by customer_name)
        customers = [r for r in DATA.get("customers", []) if "customer_name" in r]
        n = upsert_rows(cur, "customers", customers)
        print(f"  +  customers: {n}/{len(customers)} rows inserted")
        total += n

        # 2. Products (may be scattered across arrays)
        products = collect_products()
        n = upsert_rows(cur, "products", products)
        print(f"  +  products: {n}/{len(products)} rows inserted")
        total += n

        # 3. Remaining tables
        for table, pk in TABLE_ORDER:
            if table in ("customers", "products"):
                continue
            rows = DATA.get(table, [])
            if not rows:
                print(f"  skip  {table} (no data)")
                continue
            n = upsert_rows(cur, table, rows, pk)
            print(f"  +  {table}: {n}/{len(rows)} rows inserted")
            total += n

        conn.commit()
        print(f"\nDone — {total} rows committed.")
    except Exception as e:
        conn.rollback()
        print(f"\n- Error: {e}")
        raise
    finally:
        cur.close()
        conn.close()

if __name__ == "__main__":
    main()
